// Accepts JSON or form-encoded posts from any web form, phone intake or email
// parser, and builds one block of text for the model to read.

// ---------- ADD YOUR OWN FIELD NAMES HERE ----------
const ALIASES = {
  full_name: ['name', 'full_name', 'fullname', 'your-name', 'contact_name'],
  phone: ['phone', 'telephone', 'tel', 'phone_number', 'mobile', 'your-phone'],
  email: ['email', 'e-mail', 'email_address', 'your-email'],
  message: ['message', 'comments', 'details', 'description', 'job_description', 'body'],
  address: ['address', 'street', 'postcode', 'zip', 'location'],
};
// ---------------------------------------------------

function pick(body, aliases) {
  const keys = Object.keys(body);
  for (const alias of aliases) {
    const match = keys.find((k) => k.toLowerCase() === alias);
    if (match && String(body[match]).trim() !== '') return String(body[match]).trim();
  }
  return '';
}

return $input.all().map((item) => {
  const body = item.json.body || item.json || {};

  const full_name = pick(body, ALIASES.full_name);
  const phone = pick(body, ALIASES.phone);
  const email = pick(body, ALIASES.email);
  const message = pick(body, ALIASES.message);
  const address = pick(body, ALIASES.address);

  // Everything the customer actually gave us, in one block. Anything missing is
  // simply absent, which is what lets the model report it as missing.
  const enquiry_text = [
    full_name ? `Name: ${full_name}` : '',
    phone ? `Phone: ${phone}` : '',
    email ? `Email: ${email}` : '',
    address ? `Address: ${address}` : '',
    message ? `Message: ${message}` : '',
  ].filter(Boolean).join('\n');

  return { json: { full_name, phone, email, address, message, enquiry_text } };
});

