// Turns the model's structured answer into a brief a dispatcher can act on
// without opening anything else.
const lead = $('Collect Enquiry Details').first().json;
const q = $input.first().json.output || $input.first().json;

// Telegram is sent with HTML parse mode, so these three characters are escaped.
const esc = (v) => String(v ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

// hvac -> hvac, quote_request -> quote request
const label = (v) => esc(String(v ?? '').replace(/_/g, ' '));

const lines = [
  `Trade: ${label(q.trade)}`,
  `Job type: ${label(q.job_type)}`,
  `Urgency: ${label(q.urgency)}`,
  '',
  esc(q.summary),
];

if (Array.isArray(q.missing_information) && q.missing_information.length > 0) {
  lines.push('', 'Ask when you call back:');
  for (const item of q.missing_information) lines.push(`- ${esc(item)}`);
}

if (q.suggested_reply) {
  lines.push('', 'Suggested reply:', esc(q.suggested_reply));
}

lines.push(
  '',
  `Contact: ${esc(lead.full_name) || 'name not given'}`,
  `Phone: ${esc(lead.phone) || 'not given'}`,
  `Email: ${esc(lead.email) || 'not given'}`,
);

return [
  {
    json: {
      is_genuine_enquiry: q.is_genuine_enquiry,
      trade: q.trade,
      job_type: q.job_type,
      urgency: q.urgency,
      brief: lines.join('\n'),
    },
  },
];
